export interface DebouncedSave<Args extends unknown[]> {
  schedule: (...args: Args) => void;
  flush: () => void;
}

export function createDebouncedSave<Args extends unknown[]>(
  save: (...args: Args) => void | Promise<void>,
  delayMs: number,
): DebouncedSave<Args> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let pendingArgs: Args | undefined;

  function runPending(): void {
    timer = undefined;
    if (pendingArgs !== undefined) {
      const args = pendingArgs;
      pendingArgs = undefined;
      void Promise.resolve(save(...args)).catch((error: unknown) => {
        console.error(error);
      });
    }
  }

  function schedule(...args: Args): void {
    pendingArgs = args;
    if (timer !== undefined) {
      clearTimeout(timer);
    }
    timer = setTimeout(runPending, delayMs);
  }

  function flush(): void {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
    runPending();
  }

  return { schedule, flush };
}

