import { BaseDirectory, mkdir, readDir, readTextFile, rename, writeTextFile } from "@tauri-apps/plugin-fs";
import { serializeAsJSON } from "@excalidraw/excalidraw";
import type { AppState, BinaryFiles, ExcalidrawInitialDataState } from "@excalidraw/excalidraw/types";
import type { ExcalidrawElement } from "@excalidraw/excalidraw/element/types";
import { BOARDS_DIR, BOARD_FILE_EXTENSION, DEFAULT_BOARD_NAME } from "./constants";

const BASE_DIR = BaseDirectory.Document;

export async function loadBoardList(): Promise<string[]> {
  await ensureBoardsDirectory();
  const names = await listBoardNames();
  if (names.length === 0) {
    await createBoard([], DEFAULT_BOARD_NAME);
    return listBoardNames();
  }
  return names;
}

async function ensureBoardsDirectory(): Promise<void> {
  await mkdir(BOARDS_DIR, { recursive: true, baseDir: BASE_DIR });
}

async function listBoardNames(): Promise<string[]> {
  const entries = await readDir(BOARDS_DIR, { baseDir: BASE_DIR });
  return entries
    .filter((entry) => entry.isFile && entry.name.endsWith(BOARD_FILE_EXTENSION))
    .map((entry) => entry.name.slice(0, -BOARD_FILE_EXTENSION.length))
    .sort((a, b) => a.localeCompare(b));
}

export async function createBoard(
  existingNames: string[],
  desiredName: string = DEFAULT_BOARD_NAME,
): Promise<string> {
  const sanitized = sanitizeBoardName(desiredName);
  const finalName = uniqueBoardName(sanitized, existingNames);
  await writeTextFile(boardFilePath(finalName), sceneToFileContent([], {}, {}), { baseDir: BASE_DIR });
  return finalName;
}

function sanitizeBoardName(name: string): string {
  const trimmed = name.trim().replace(/[/:]/g, "-");
  return trimmed.length > 0 ? trimmed : DEFAULT_BOARD_NAME;
}

function uniqueBoardName(desiredName: string, existingNames: string[]): string {
  if (!existingNames.includes(desiredName)) {
    return desiredName;
  }
  let suffix = 2;
  let candidate = `${desiredName} ${suffix}`;
  while (existingNames.includes(candidate)) {
    suffix += 1;
    candidate = `${desiredName} ${suffix}`;
  }
  return candidate;
}

function boardFilePath(name: string): string {
  return `${BOARDS_DIR}/${name}${BOARD_FILE_EXTENSION}`;
}

function sceneToFileContent(
  elements: readonly ExcalidrawElement[],
  appState: Partial<AppState>,
  files: BinaryFiles,
): string {
  const serialized = serializeAsJSON(elements, appState, files, "local");
  return JSON.stringify(JSON.parse(serialized), null, 2);
}

export async function readBoardScene(name: string): Promise<ExcalidrawInitialDataState> {
  const raw = await readTextFile(boardFilePath(name), { baseDir: BASE_DIR });
  return JSON.parse(raw) as ExcalidrawInitialDataState;
}

export async function saveBoardScene(
  name: string,
  elements: readonly ExcalidrawElement[],
  appState: AppState,
  files: BinaryFiles,
): Promise<void> {
  await writeTextFile(boardFilePath(name), sceneToFileContent(elements, appState, files), { baseDir: BASE_DIR });
}

export async function renameBoard(
  oldName: string,
  desiredNewName: string,
  existingNames: string[],
): Promise<string> {
  const sanitized = sanitizeBoardName(desiredNewName);
  const finalName = uniqueBoardName(sanitized, existingNames);
  if (finalName !== oldName) {
    await rename(boardFilePath(oldName), boardFilePath(finalName), {
      oldPathBaseDir: BASE_DIR,
      newPathBaseDir: BASE_DIR,
    });
  }
  return finalName;
}

