function sceneToFileContent(
  elements: readonly ExcalidrawElement[],
  appState: Partial<AppState>,
  files: BinaryFiles,
): string {
  const serialized = serializeAsJSON(elements, appState, files, "local");
  return JSON.stringify(JSON.parse(serialized), null, 2);
}

export async function readBoardScene(name: string): Promise<ExcalidrawInitialDataState> {
  const raw = await readTextFile(boardFilePath(name), { baseDir: BASE_DIR });
  return JSON.parse(raw) as ExcalidrawInitialDataState;
}

export async function saveBoardScene(
  name: string,
  elements: readonly ExcalidrawElement[],
  appState: AppState,
  files: BinaryFiles,
): Promise<void> {
  await writeTextFile(boardFilePath(name), sceneToFileContent(elements, appState, files), { baseDir: BASE_DIR });
}

export async function renameBoard(
  oldName: string,
  desiredNewName: string,
  existingNames: string[],
): Promise<string> {
  const sanitized = sanitizeBoardName(desiredNewName);
  const finalName = uniqueBoardName(sanitized, existingNames);
  if (finalName !== oldName) {
    await rename(boardFilePath(oldName), boardFilePath(finalName), {
      oldPathBaseDir: BASE_DIR,
      newPathBaseDir: BASE_DIR,
    });
  }
  return finalName;
}

