// INFRASTRUCTURE
import { useCallback, useEffect, useRef, useState } from "react";
import type { MutableRefObject } from "react";
import type { AppState, BinaryFiles, ExcalidrawInitialDataState } from "@excalidraw/excalidraw/types";
import type { ExcalidrawElement } from "@excalidraw/excalidraw/element/types";
import { createBoard, loadBoardList, readBoardScene, renameBoard, saveBoardScene } from "./boards";
import { createDebouncedSave } from "./autosave";
import type { DebouncedSave } from "./autosave";
import { AUTOSAVE_DELAY_MS, DEFAULT_BOARD_NAME } from "./constants";

interface BoardSessionState {
  boards: string[];
  activeBoard: string | null;
  initialData: ExcalidrawInitialDataState | null;
  isReady: boolean;
}

interface BoardSession extends BoardSessionState {
  onSceneChange: (elements: readonly ExcalidrawElement[], appState: AppState, files: BinaryFiles) => void;
  onSelectBoard: (name: string) => void;
  onCreateBoard: () => void;
  onRenameBoard: (oldName: string, newName: string) => void;
}

type SetSessionState = (updater: BoardSessionState | ((prev: BoardSessionState) => BoardSessionState)) => void;
type SaveArgs = [string, readonly ExcalidrawElement[], AppState, BinaryFiles];

const INITIAL_STATE: BoardSessionState = {
  boards: [],
  activeBoard: null,
  initialData: null,
  isReady: false,
};

const sortNames = (names: string[]): string[] => [...names].sort((a, b) => a.localeCompare(b));

// ORCHESTRATOR
export function useBoardSession(): BoardSession {
  const [state, setState] = useState<BoardSessionState>(INITIAL_STATE);
  const justLoadedRef = useRef(false);
  const debouncedSaveRef = useRef<DebouncedSave<SaveArgs>>(createDebouncedSave(saveBoardScene, AUTOSAVE_DELAY_MS));

  useEffect(() => {
    initializeSession(setState, justLoadedRef);
  }, []);

  const onSceneChange = useCallback(
    (elements: readonly ExcalidrawElement[], appState: AppState, files: BinaryFiles) => {
      handleSceneChange(state.activeBoard, elements, appState, files, justLoadedRef, debouncedSaveRef.current);
    },
    [state.activeBoard],
  );

  const onSelectBoard = useCallback((name: string) => {
    switchToBoard(name, setState, justLoadedRef, debouncedSaveRef.current);
  }, []);

  const onCreateBoard = useCallback(() => {
    createAndSwitchBoard(state.boards, setState, justLoadedRef, debouncedSaveRef.current);
  }, [state.boards]);

  const onRenameBoard = useCallback(
    (oldName: string, newName: string) => {
      commitRename(oldName, newName, state.boards, setState, debouncedSaveRef.current);
    },
    [state.boards],
  );

  return { ...state, onSceneChange, onSelectBoard, onCreateBoard, onRenameBoard };
}

// FUNCTIONS
async function initializeSession(setState: SetSessionState, justLoadedRef: MutableRefObject<boolean>): Promise<void> {
  const boards = await loadBoardList();
  const activeBoard = boards[0] ?? null;
  const initialData = activeBoard !== null ? await readBoardScene(activeBoard) : null;
  justLoadedRef.current = true;
  setState({ boards, activeBoard, initialData, isReady: true });
}

function handleSceneChange(
  activeBoard: string | null,
  elements: readonly ExcalidrawElement[],
  appState: AppState,
  files: BinaryFiles,
  justLoadedRef: MutableRefObject<boolean>,
  debouncedSave: DebouncedSave<SaveArgs>,
): void {
  if (justLoadedRef.current) {
    justLoadedRef.current = false;
    return;
  }
  if (activeBoard === null) {
    return;
  }
  debouncedSave.schedule(activeBoard, elements, appState, files);
}

async function switchToBoard(
  name: string,
  setState: SetSessionState,
  justLoadedRef: MutableRefObject<boolean>,
  debouncedSave: DebouncedSave<SaveArgs>,
): Promise<void> {
  debouncedSave.flush();
  const initialData = await readBoardScene(name);
  justLoadedRef.current = true;
  setState((prev) => ({ ...prev, activeBoard: name, initialData }));
}

async function createAndSwitchBoard(
  boards: string[],
  setState: SetSessionState,
  justLoadedRef: MutableRefObject<boolean>,
  debouncedSave: DebouncedSave<SaveArgs>,
): Promise<void> {
  debouncedSave.flush();
  const name = await createBoard(boards, DEFAULT_BOARD_NAME);
  const initialData = await readBoardScene(name);
  justLoadedRef.current = true;
  setState((prev) => ({
    ...prev,
    boards: sortNames([...prev.boards, name]),
    activeBoard: name,
    initialData,
  }));
}

async function commitRename(
  oldName: string,
  newName: string,
  boards: string[],
  setState: SetSessionState,
  debouncedSave: DebouncedSave<SaveArgs>,
): Promise<void> {
  debouncedSave.flush();
  const others = boards.filter((existing) => existing !== oldName);
  const finalName = await renameBoard(oldName, newName, others);
  setState((prev) => ({
    ...prev,
    boards: sortNames(prev.boards.map((existing) => (existing === oldName ? finalName : existing))),
    activeBoard: prev.activeBoard === oldName ? finalName : prev.activeBoard,
  }));
}

