import { useState } from "react";
import "./Sidebar.css";

interface SidebarProps {
  boards: string[];
  activeBoard: string | null;
  onSelectBoard: (name: string) => void;
  onCreateBoard: () => void;
  onRenameBoard: (oldName: string, newName: string) => void;
}

export function Sidebar(props: SidebarProps) {
  const { boards, activeBoard, onSelectBoard, onCreateBoard, onRenameBoard } = props;
  const [collapsed, setCollapsed] = useState(false);
  const [editingBoard, setEditingBoard] = useState<string | null>(null);
  const [draftName, setDraftName] = useState("");

  function startEditing(name: string): void {
    setEditingBoard(name);
    setDraftName(name);
  }

  function commitEditing(): void {
    if (editingBoard !== null && draftName.trim().length > 0 && draftName !== editingBoard) {
      onRenameBoard(editingBoard, draftName);
    }
    setEditingBoard(null);
  }

  function cancelEditing(): void {
    setEditingBoard(null);
  }

  if (collapsed) {
    return (
      <div className="sidebar sidebar-collapsed">
        <button className="sidebar-toggle" onClick={() => setCollapsed(false)}>
          {">"}
        </button>
      </div>
    );
  }

  return (
    <div className="sidebar">
      <div className="sidebar-header">
        <button className="sidebar-toggle" onClick={() => setCollapsed(true)}>
          {"<"}
        </button>
        <button className="sidebar-new-board" onClick={onCreateBoard}>
          + New Board
        </button>
      </div>
      <ul className="sidebar-list">
        {boards.map((name) => (
          <li key={name} className={name === activeBoard ? "sidebar-item sidebar-item-active" : "sidebar-item"}>
            {editingBoard === name ? (
              <input
                className="sidebar-item-input"
                value={draftName}
                autoFocus
                onChange={(event) => setDraftName(event.currentTarget.value)}
                onBlur={commitEditing}
                onKeyDown={(event) => {
                  if (event.key === "Enter") {
                    commitEditing();
                  }
                  if (event.key === "Escape") {
                    cancelEditing();
                  }
                }}
              />
            ) : (
              <button
                className="sidebar-item-button"
                onClick={() => onSelectBoard(name)}
                onDoubleClick={() => startEditing(name)}
              >
                {name}
              </button>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

