import { Excalidraw } from "@excalidraw/excalidraw";
import "@excalidraw/excalidraw/index.css";
import "./App.css";
import { Sidebar } from "./Sidebar";
import { useBoardSession } from "./useBoardSession";

function App() {
  const session = useBoardSession();

  if (!session.isReady || session.activeBoard === null) {
    return <div className="canvas-app" />;
  }

  return (
    <div className="app-shell">
      <Sidebar
        boards={session.boards}
        activeBoard={session.activeBoard}
        onSelectBoard={session.onSelectBoard}
        onCreateBoard={session.onCreateBoard}
        onRenameBoard={session.onRenameBoard}
      />
      <div className="canvas-app">
        <Excalidraw
          key={session.activeBoard}
          theme="dark"
          initialData={session.initialData ?? undefined}
          onChange={session.onSceneChange}
        />
      </div>
    </div>
  );
}

export default App;

